# ---- 개인정보 문서/매니페스트 ----
def test_privacy_policy_docs_exist():
    assert (ROOT / "docs" / "privacy-policy.ko.md").exists()
    assert (ROOT / "docs" / "privacy-policy.en.md").exists()


def test_privacy_manifest_artifact_exists():
    app_json = ROOT / "app.json"
    docs_manifest = ROOT / "docs" / "privacy-manifest.md"
    assert app_json.exists() or docs_manifest.exists(), \
        "Apple privacy manifest 정보 필요"


def test_privacy_manifest_in_app_json():
    app_json = ROOT / "app.json"
    if not app_json.exists():
        return  # user choice; docs/privacy-manifest.md 커버
    data = json.loads(app_json.read_text(encoding="utf-8"))
    ios = data.get("expo", {}).get("ios", {})
    manifests = ios.get("privacyManifests", {})
    assert manifests.get("NSPrivacyTracking") is False
    types = [x["NSPrivacyCollectedDataType"] for x in manifests.get("NSPrivacyCollectedDataTypes", [])]
    assert "NSPrivacyCollectedDataTypeDateOfBirth" in types
    assert "NSPrivacyCollectedDataTypeCoarseLocation" in types


